def public_id(label, pk, link_date):
    """Frozen copy of common.public_ids.make_public_id (a test checks they agree)."""
    message = f'{label}:{pk}:{link_date.astimezone(UTC).isoformat(timespec="microseconds")}'
    digest = salted_hmac('public-id', message, algorithm='sha256').digest()
    return base64.b32encode(digest[:16]).decode().lower().rstrip('=')


def fill_public_ids(apps, schema_editor):
    """Existing records: link date = creation date, public id derived from it."""
    for name in ('Category', 'Gallery', 'Photo'):
        model = apps.get_model('gallery', name)
        for obj in model.objects.filter(public_id__isnull=True).only('pk', 'created_at'):
            model.objects.filter(pk=obj.pk).update(
                link_date=obj.created_at, public_id=public_id(f'gallery.{name.lower()}', obj.pk, obj.created_at),
            )


